# -*- coding: utf-8 -*-
# patch_iskra_contract.py
# ============================================================
# ПАТЧ: Искра приведена к CHAIN_CONTRACT — единый стандарт памяти.
# Спринт 45 · 2026-06-16
#
# Аудит движков (кто что ждёт/отдаёт) показал: моя Искра вела память
# в своём файле iskra_history_dna.json — МИМО штатной системы. А в цехе
# уже есть trading_state.json + hooks.on_before_run, которые дают Искре
# prev_t1_status/prev_zero_point_price (как требует контракт). Морж
# будет читать память Искры ИМЕННО оттуда.
#
# Что изменено в iskra_live.py (движок и hooks НЕ трогаются):
#   1. Память Искры -> штатный trading_state["iskra"] через
#      hooks.load_trading_state / save_trading_state (один источник).
#   2. Велосипед iskra_history_dna.json удалён.
#   3. Искре даются ГОТОВЫЕ пивоты движка (market_data.ao.pivots)
#      вместо сырого price_tail — голос синхронизирован с движком.
#   4. В промпт-контекст добавлен закон: signal.t1_status = флаг
#      divergence_ao движка (голос шире, сигнал = движок).
#
# Бэкап (.bak). Запуск из корня репо:  python patch_iskra_contract.py
# ============================================================
import base64, os, shutil
FILES = {
    "studio/modules/trading/iskra_live.py": ""
}
def main():
    root = os.getcwd()
    print("=== ПАТЧ: Искра под CHAIN_CONTRACT (память в trading_state) ===")
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    # Удаляем велосипедный файл памяти, если он успел появиться
    old = os.path.join(root, "studio", "modules", "trading", "state", "iskra_history_dna.json")
    if os.path.exists(old):
        os.remove(old)
        print("  [DEL] iskra_history_dna.json (велосипед удалён)")
    print("=== ГОТОВО ===")
    print("Память Искры теперь в trading_state.json — там же её прочитает Морж.")
    print("Прогони РЫНОК: Искра должна работать как раньше, но память —")
    print("в state/trading_state.json (ключ iskra). Проверь файл после прогона.")
if __name__ == "__main__":
    main()
